@_documentation(visibility: private)
#endif
public struct FfiConverterTypeCoreError: FfiConverterRustBuffer {
    typealias SwiftType = CoreError

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> CoreError {
        let variant: Int32 = try readInt(&buf)
        switch variant {

        

        
        case 1: return .NotFound(
            what: try FfiConverterString.read(from: &buf)
            )
        case 2: return .Locked
        case 3: return .Unavailable(
            reason: try FfiConverterString.read(from: &buf)
            )
        case 4: return .Corrupt(
            detail: try FfiConverterString.read(from: &buf)
            )
        case 5: return .NeedsMigration(
            from: try FfiConverterUInt32.read(from: &buf), 
            to: try FfiConverterUInt32.read(from: &buf)
            )
        case 6: return .NewerStore(
            appVersion: try FfiConverterString.read(from: &buf)
            )
        case 7: return .InvalidInput(
            field: try FfiConverterString.read(from: &buf), 
            message: try FfiConverterString.read(from: &buf)
            )
        case 8: return .Conflict(
            detail: try FfiConverterString.read(from: &buf)
            )
        case 9: return .ResetRequired(
            generation: try FfiConverterUInt64.read(from: &buf)
            )
        case 10: return .Cancelled
        case 11: return .Internal(
            detail: try FfiConverterString.read(from: &buf)
            )

         default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: CoreError, into buf: inout [UInt8]) {
        switch value {

        

        
        
        case let .NotFound(what):
            writeInt(&buf, Int32(1))
            FfiConverterString.write(what, into: &buf)
            
        
        case .Locked:
            writeInt(&buf, Int32(2))
        
        
        case let .Unavailable(reason):
            writeInt(&buf, Int32(3))
            FfiConverterString.write(reason, into: &buf)
            
        
        case let .Corrupt(detail):
            writeInt(&buf, Int32(4))
            FfiConverterString.write(detail, into: &buf)
            
        
        case let .NeedsMigration(from,to):
            writeInt(&buf, Int32(5))
            FfiConverterUInt32.write(from, into: &buf)
            FfiConverterUInt32.write(to, into: &buf)
            
        
        case let .NewerStore(appVersion):
            writeInt(&buf, Int32(6))
            FfiConverterString.write(appVersion, into: &buf)
            
        
        case let .InvalidInput(field,message):
            writeInt(&buf, Int32(7))
            FfiConverterString.write(field, into: &buf)
            FfiConverterString.write(message, into: &buf)
            
        
        case let .Conflict(detail):
            writeInt(&buf, Int32(8))
            FfiConverterString.write(detail, into: &buf)
            
        
        case let .ResetRequired(generation):
            writeInt(&buf, Int32(9))
            FfiConverterUInt64.write(generation, into: &buf)
            
        
        case .Cancelled:
            writeInt(&buf, Int32(10))
        
        
        case let .Internal(detail):
            writeInt(&buf, Int32(11))
            FfiConverterString.write(detail, into: &buf)
            
        }
    }
}


